export function normalizeLanguage(language: string | undefined): string | undefined { return language ? aliases[language.trim().toLowerCase()] : undefined; }
export function languageForPath(path: string): string | undefined { const name = path.slice(Math.max(path.lastIndexOf("/"), path.lastIndexOf("\\")) + 1).toLowerCase(); if (fileNames[name]) return fileNames[name]; if (name.startsWith("dockerfile.")) return "dockerfile"; const dot = name.lastIndexOf("."); if (dot <= 0) return undefined; return normalizeLanguage(extensions[name.slice(dot + 1)] ?? name.slice(dot + 1)); }
export function languageForContentType(contentType: string): string | undefined { const type = contentType.split(";")[0]!.trim().toLowerCase(); return mediaTypes[type] ?? (type.endsWith("+json") ? "json" : type.endsWith("+xml") ? "xml" : undefined); }
